xpath.script:

document.addEventListener('DOMContentLoaded', () => {
    const canvas = document.getElementById('bg-canvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const switchBtn = document.getElementById('mode-switch-wrapper');
    const icon = document.getElementById('mode-icon');

    let particles = [];
    let stars = []; 
    const speedFactor = 2.5;
    let pColor = "0, 0, 0";

    function updateThemeVariables() {
        const style = getComputedStyle(document.body);
        pColor = style.getPropertyValue('--particle-color').trim() || "0, 0, 0";
    }

    const savedMode = localStorage.getItem('theme-mode');
    if (savedMode === 'dark') {
        document.body.classList.add('dark-mode');
        if(icon) icon.className = 'fa fa-moon-o';
    }
    updateThemeVariables();

    if (switchBtn) {
        switchBtn.addEventListener('click', () => {
            document.body.classList.toggle('dark-mode');
            const isDark = document.body.classList.contains('dark-mode');
            if(icon) icon.className = isDark ? 'fa fa-moon-o' : 'fa fa-sun-o';
            localStorage.setItem('theme-mode', isDark ? 'dark' : 'light');
            updateThemeVariables();
        });
    }

    function resize() { 
        canvas.width = window.innerWidth; 
        canvas.height = window.innerHeight; 
    }

    class Star {
        constructor() {
            this.x = Math.random() * canvas.width;
            this.y = Math.random() * canvas.height;
            this.size = Math.random() * 1.5;
            this.opacity = Math.random() * 0.2;
            this.factor = (Math.random() * 0.005) * speedFactor;
        }
        draw(color) {
            this.opacity += this.factor;
            if (this.opacity > 0.3 || this.opacity < 0.05) this.factor *= -1;
            ctx.fillStyle = "rgba(" + color + ", " + this.opacity + ")";
            ctx.beginPath();
            ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
            ctx.fill();
        }
    }

    class Particle {
        constructor() {
            this.x = Math.random() * canvas.width;
            this.y = Math.random() * canvas.height;
            this.size = Math.random() * 2 + 1;
            this.vx = (Math.random() - 0.5) * speedFactor;
            this.vy = (Math.random() - 0.5) * speedFactor;
        }
        update() {
            this.x += this.vx; 
            this.y += this.vy;
            if (this.x < 0 || this.x > canvas.width) this.vx *= -1;
            if (this.y < 0 || this.y > canvas.height) this.vy *= -1;
        }
        draw(color) {
            ctx.fillStyle = "rgb(" + color + ")";
            ctx.beginPath();
            ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
            ctx.fill();
        }
    }

    function init() {
        particles = []; stars = [];
        for (let i = 0; i < 100; i++) stars.push(new Star());
        let count = (canvas.height * canvas.width) / 6000; 
        for (let i = 0; i < count; i++) particles.push(new Particle());
    }

    function connect(color) {
        const maxDistSq = 180 * 180;
        for (let a = 0; a < particles.length; a++) {
            for (let b = a + 1; b < particles.length; b++) {
                let dx = particles[a].x - particles[b].x;
                let dy = particles[a].y - particles[b].y;
                let distSq = dx * dx + dy * dy;
                if (distSq < maxDistSq) { 
                    let opacity = (1 - (distSq / maxDistSq)) * 0.4;
                    ctx.strokeStyle = "rgba(" + color + ", " + opacity + ")";
                    ctx.lineWidth = 1.0;
                    ctx.beginPath();
                    ctx.moveTo(particles[a].x, particles[a].y);
                    ctx.lineTo(particles[b].x, particles[b].y);
                    ctx.stroke();
                }
            }
        }
    }

    function animate() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        stars.forEach(s => s.draw(pColor));
        particles.forEach(p => { p.update(); p.draw(pColor); });
        connect(pColor);
        requestAnimationFrame(animate);
    }

    window.addEventListener('resize', () => { resize(); init(); });
    resize(); init(); animate();
});
